/**
 * @suppress
 */
public object FfiConverterTypeChatCore: FfiConverter<ChatCore, Pointer> {

    override fun lower(value: ChatCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ChatCore {
        return ChatCore(value)
    }

    override fun read(buf: ByteBuffer): ChatCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ChatCore) = 8UL

    override fun write(value: ChatCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



